def template_pred(g,outcolor):
 H,W=len(g),len(g[0]); pts=[(r,c) for r in range(H) for c in range(W) if g[r][c]==outcolor]
 r0=min(r for r,c in pts);c0=min(c for r,c in pts); off=[(r-r0,c-c0) for r,c in pts];h=max(r for r,c in off)+1;w=max(c for r,c in off)+1
 paint=set();matches=[]
 for r in range(H-h+1):
  for c in range(W-w+1):
   loc=[(r+dr,c+dc) for dr,dc in off]
   if all(g[x][y]==0 for x,y in loc): matches.append((r,c));paint.update(loc)
 return paint,matches
